-- Generated by Ergasterion from a product declaration. Do not edit by hand.
{{ config(materialized='table') }}

with
quarantined as (
    select
        fund_external_lookup_key,
        fund_business_key,
        fund_entity_count,
        violation_00,
        violation_01,
        violation_02
    from {{ ref("investment__fund_external_index__checked_post") }}
),
violations as (
    select
        'fund_external_lookup_key_not_null' as rule_name,
        fund_external_lookup_key,
        fund_business_key,
        fund_entity_count
    from quarantined
    where violation_00

    union all

    select
        'fund_external_lookup_key_unique' as rule_name,
        fund_external_lookup_key,
        fund_business_key,
        fund_entity_count
    from quarantined
    where violation_01

    union all

    select
        'fund_entity_count_range' as rule_name,
        fund_external_lookup_key,
        fund_business_key,
        fund_entity_count
    from quarantined
    where violation_02
)

select
    rule_name,
    fund_external_lookup_key,
    fund_business_key,
    fund_entity_count
from violations
